// vel.gg Checkpoints: the extension's isolated-world script on vel.gg pages. Keeps the checkpoints in
// chrome.storage.local, tells page.js what to write into OPFS, shows the toasts and handles the F8 save key.
// mod-files.js (generated by build-mod.mjs) runs first and sets globalThis.VELGG_CP_MOD_FILES.
(() => {
  'use strict';
  const TAG = 'velgg-checkpoints';
  const MOD = 'checkpoint';
  const SAVE_KEY = 'F8';
  const MAX_ROUND = 15, MAX_MANUAL = 20;
  // vel.gg maps.js MAP_LIST: Five's pack is OPFS "pack", every other map's "pack-<slug>"
  const MAPS = {
    zombie_pentagon: { name: 'Five', pack: 'pack' },
    zombie_theater: { name: 'Kino der Toten', pack: 'pack-kino' },
    zombie_cod5_factory: { name: 'Der Riese', pack: 'pack-riese' },
    zombie_cod5_prototype: { name: 'Nacht der Untoten', pack: 'pack-nacht' },
    zombie_cod5_asylum: { name: 'Verrückt', pack: 'pack-verruckt' },
    zombie_cod5_sumpf: { name: 'Shi No Numa', pack: 'pack-shinonuma' },
    zombie_cosmodrome: { name: 'Ascension', pack: 'pack-ascension' },
    zombie_coast: { name: 'Call of the Dead', pack: 'pack-cotd' },
    zombie_temple: { name: 'Shangri-La', pack: 'pack-shangrila' },
    zombie_moon: { name: 'Moon', pack: 'pack-moon' },
  };
  // what a saved field may hold (the mod's own alphabet); anything else is refused before it reaches a .cfg line
  const SAFE = /^[A-Za-z0-9_|:@#=.\-]*$/;

  const toMain = msg => window.postMessage({ [TAG]: 'to-main', ...msg }, location.origin);
  const store = {
    get: keys => chrome.storage.local.get(keys),
    set: items => chrome.storage.local.set(items),
  };
  let engineZone = null;
  const engineLog = []; // mod-related engine console lines this page load (page.js filters them)
  let logWarned = false;
  let modStatus = []; // the mods' own status lines, read from the engine's memory (page.js scan)
  let engineMods = [], engineStartedAt = 0;

  //---------------------------------------------------------------------------------------------------------------
  // the load file for each map's pack
  //---------------------------------------------------------------------------------------------------------------
  function cfgFor(checkpoint, token) {
    if (!checkpoint || !token || !checkpoint.chunks.every(c => SAFE.test(c) && c.length <= 900)) return 'set cp_load "0"\n';
    return [`set cp_token "${token}"`, `set cp_n "${checkpoint.chunks.length}"`,
      ...checkpoint.chunks.map((c, i) => `set cp_${i} "${c}"`), 'set cp_load "1"', ''].join('\n');
  }
  async function cfgs(zones = Object.keys(MAPS)) {
    const { armed = {} } = await store.get('armed');
    const out = {};
    // armed[zone] = { token, checkpoint }: a copy, so the auto slot moving on does not change what loads
    for (const zone of zones) out[MAPS[zone].pack] = cfgFor(armed[zone]?.checkpoint, armed[zone]?.token);
    return out;
  }
  // a mod's mod.ff, from the extension's own files: fetched here, or by the service worker if the page's
  // cross-origin rules stop this fetch. stamp = the first 12 hex digits of its SHA-256 (a version code to compare).
  const binaries = new Map();
  async function readBinary(path) {
    try {
      const response = await fetch(chrome.runtime.getURL(path));
      if (response.ok) return await response.arrayBuffer();
    } catch { /* below */ }
    const reply = await chrome.runtime.sendMessage({ type: 'read-file', path });
    if (!reply?.base64) throw new Error(reply?.error ?? 'could not read ' + path);
    return Uint8Array.from(atob(reply.base64), c => c.charCodeAt(0)).buffer;
  }
  function loadBinary(path) {
    if (!binaries.has(path)) binaries.set(path, readBinary(path).then(async buffer => {
      const digest = new Uint8Array(await crypto.subtle.digest('SHA-256', buffer));
      return { buffer, size: buffer.byteLength, stamp: Array.from(digest.slice(0, 6), b => b.toString(16).padStart(2, '0')).join('') };
    }));
    return binaries.get(path);
  }
  const sentBinaries = new Set();

  // the renderer: vel.gg's engine.js rendererChoice() reads sessionStorage kisak-renderer before ?renderer=, once per
  // page load (before the download). "webgl2" forces WebGL2; "auto" removes the override, but only one this extension
  // set (velgg-cp-renderer marks it), never the page's own after a WebGPU failure.
  function applyRenderer(settings) {
    try {
      if (settings.renderer === 'webgl2') {
        sessionStorage.setItem('kisak-renderer', 'webgl2');
        sessionStorage.setItem('velgg-cp-renderer', '1');
      } else if (sessionStorage.getItem('velgg-cp-renderer')) {
        sessionStorage.removeItem('kisak-renderer');
        sessionStorage.removeItem('velgg-cp-renderer');
      }
    } catch { /* storage blocked: vel.gg chooses as usual */ }
  }

  async function install(withFiles) {
    const { settings = {} } = await store.get('settings');
    applyRenderer(settings);
    const enabled = settings.enabled !== false;
    const mods = globalThis.velggModConfig(settings);
    // first without the mod.ff sizes (page.js leaves an fs_game mod out until its file is written), so the
    // download worker hears about the mods at once
    toMain({ type: 'config', enabled, mods });
    if (!enabled) return;
    toMain({ type: 'install', files: withFiles ? globalThis.VELGG_CP_MOD_FILES : undefined, cfgs: await cfgs() });
    const send = (target, file, bases) => {
      if (sentBinaries.has(target)) return;
      sentBinaries.add(target);
      toMain({ type: 'install-binary', path: target, buffer: file.buffer.slice(0), stamp: file.stamp, bases });
    };
    for (const m of mods.filter(m => m.fsGame)) {
      const def = globalThis.VELGG_MODS.find(d => d.id === m.id);
      try {
        const ff = await loadBinary(def.ff);
        Object.assign(m, { ffSize: ff.size, ffStamp: ff.stamp });
        const target = `${m.fsGame}/mod.ff`;
        // every map pack (fs_b) and the engine's home folders (fs_h: solo, co-op host, co-op friend): the engine
        // opens <fs_homepath>/<fs_game>/mod.ff natively, and vel.gg's own cstest mod.ff comes in the pack
        const packs = [...new Set(Object.values(MAPS).map(m => m.pack + '/files'))];
        send(target, ff, [...packs, 'user', 'user/coop-host', 'user/coop-join']);
        // the other files (halo.iwd: the textures) only in the packs: the engine's search path is
        // <fs_b>/<fs_game> (its log: "Current search path: /opfs/pack-kino/files/mods/halo"), never the home folder
        m.extraFiles = [];
        for (const path of def.extras ?? []) {
          const file = await loadBinary(path), extra = `${m.fsGame}/${path.split('/').pop()}`;
          m.extraFiles.push({ path: extra, stamp: file.stamp });
          send(extra, file, packs);
        }
      } catch (error) {
        console.warn(`[checkpoints] ${def.name}: a file is missing from the extension (${[def.ff, ...(def.extras ?? [])].join(', ')})`, error);
        showToast(`${def.name}: its mod.ff or textures are missing from the extension`, 4000);
      }
    }
    if (mods.some(m => m.fsGame)) toMain({ type: 'config', enabled, mods });
  }

  //---------------------------------------------------------------------------------------------------------------
  // saving what page.js read
  //---------------------------------------------------------------------------------------------------------------
  function fieldsOf(chunks) {
    const f = {};
    for (const part of chunks.join('#').split('#')) {
      const eq = part.indexOf('=');
      if (eq > 0 && part.slice(0, eq) !== 'd') f[part.slice(0, eq)] = part.slice(eq + 1);
    }
    return f;
  }
  async function saveSnapshot(msg) {
    if (!MAPS[msg.zone] || !Array.isArray(msg.chunks) || !msg.chunks.length || !msg.chunks.every(c => typeof c === 'string' && SAFE.test(c))) return;
    const f = fieldsOf(msg.chunks);
    const round = Number(f.round);
    if (f.v !== '1' || !Number.isInteger(round)) return;
    const key = 'cp:' + msg.zone;
    const list = (await store.get(key))[key] ?? [];
    const auto = list.find(c => c.kind === 'auto');
    if (msg.reason !== 'manual' && auto?.gid === msg.gid && auto.seq === msg.seq) return; // nothing new
    const base = { zone: msg.zone, map: f.map, round, score: Number(f['p0.score']) || 0, players: Number(f.players) || 1,
      gid: msg.gid, seq: msg.seq, chunks: msg.chunks, savedAt: Date.now() };
    let toast = null;
    if (msg.reason === 'manual') {
      list.push({ ...base, id: 'm' + Date.now(), kind: 'manual' });
      const manual = list.filter(c => c.kind === 'manual');
      if (manual.length > MAX_MANUAL) list.splice(list.indexOf(manual[0]), 1);
      toast = `Checkpoint saved: round ${round}`;
    }
    // one auto slot per map, always the newest
    if (auto) Object.assign(auto, base); else list.push({ ...base, id: 'auto', kind: 'auto' });
    // the first state seen in each round of this game is that round's checkpoint
    if (!list.some(c => c.kind === 'round' && c.gid === msg.gid && c.round === round)) {
      list.push({ ...base, id: 'r' + Date.now(), kind: 'round' });
      const rounds = list.filter(c => c.kind === 'round');
      if (rounds.length > MAX_ROUND) list.splice(list.indexOf(rounds[0]), 1);
      toast ??= `Round ${round} checkpoint`;
    }
    await store.set({ [key]: list });
    if (toast) showToast(toast);
  }
  async function onAcks(msg) {
    const { armed = {} } = await store.get('armed');
    const a = armed[msg.zone];
    if (!a || !Array.isArray(msg.tokens) || !msg.tokens.includes(a.token)) return;
    delete armed[msg.zone];
    await store.set({ armed }); // storage.onChanged rewrites the cfg
    showToast('Checkpoint loaded');
  }

  //---------------------------------------------------------------------------------------------------------------
  // toasts and the save key
  //---------------------------------------------------------------------------------------------------------------
  let toastEl = null, toastTimer = 0;
  function showToast(text, ms = 2600) {
    if (!document.body) return;
    if (!toastEl) {
      toastEl = document.createElement('div');
      toastEl.style.cssText = 'position:fixed;top:16px;left:50%;transform:translateX(-50%);z-index:2147483647;' +
        'background:rgba(20,20,20,.88);color:#f3efe6;font:600 14px/1.3 system-ui,sans-serif;padding:8px 14px;' +
        'border-radius:6px;border:1px solid rgba(255,255,255,.15);pointer-events:none;transition:opacity .25s;opacity:0';
    }
    // a fullscreen <canvas> cannot hold the toast; its own fullscreen container can
    const full = document.fullscreenElement;
    (full && !/^(CANVAS|VIDEO)$/.test(full.tagName) ? full : document.body).append(toastEl);
    toastEl.textContent = text;
    toastEl.style.opacity = '1';
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => { toastEl.style.opacity = '0'; }, ms);
  }
  window.addEventListener('keydown', event => {
    if (event.code !== SAVE_KEY || event.repeat) return;
    toMain({ type: 'scan', reason: 'manual' });
  }, true);

  //---------------------------------------------------------------------------------------------------------------
  // wiring
  //---------------------------------------------------------------------------------------------------------------
  window.addEventListener('message', event => {
    const msg = event.data;
    if (event.source !== window || !msg || msg[TAG] !== 'to-ext') return;
    if (msg.type === 'hello') install(true);
    else if (msg.type === 'snapshot') saveSnapshot(msg);
    else if (msg.type === 'acks') onAcks(msg);
    else if (msg.type === 'scan-result' && msg.reason === 'manual' && msg.error) showToast(msg.error, 3500);
    else if (msg.type === 'install-error') console.warn('[checkpoints] could not write the mod files:', msg.message);
    else if (msg.type === 'mod-status' && Array.isArray(msg.lines)) modStatus = msg.lines.filter(l => typeof l === 'string').slice(0, 5);
    else if (msg.type === 'engine-log' && Array.isArray(msg.lines)) {
      // the first 200 lines (startup: files, mods, scripts) stay; after that, the newest 200
      engineLog.push(...msg.lines.filter(l => typeof l === 'string').map(l => l.slice(0, 400)));
      if (engineLog.length > 400) engineLog.splice(200, engineLog.length - 400);
      if (!logWarned && msg.lines.some(l => /halo|mod\.ff/i.test(l) && /error|unknown|couldn't|could not|can't|cannot|not found|missing|failed/i.test(l))) {
        logWarned = true;
        showToast('The engine reported a problem with the Halo mod: see the engine log in the popup', 5000);
      }
    }
    else if (msg.type === 'binary-ready' && msg.wrote > 0) showToast(/\.iwd$/.test(msg.path)
      ? 'Halo textures copied in: ready for the next map start' : 'Halo weapons copied in', 3500);
    else if (msg.type === 'engine') {
      if (msg.status !== 'ff-skipped') engineZone = msg.status === 'started' && msg.role !== 'join' ? msg.zone : null;
      if (msg.status === 'started') { engineMods = Array.isArray(msg.mods) ? msg.mods : []; engineStartedAt = Date.now(); modStatus = []; }
      // the mod.ff version code: in co-op every player's must match
      const ff = /^[a-f0-9]{12}$/.test(msg.ffStamp ?? '') ? ` (version ${msg.ffStamp.slice(0, 6)})` : '';
      if (msg.status === 'fs_game') showToast('Mods are off with Counter-Strike guns');
      else if (msg.status === 'ff-skipped') {
        const name = globalThis.VELGG_MODS.find(m => m.id === msg.id)?.name ?? msg.id;
        showToast(msg.pending ? `${name} was still being copied in: restart the map to use it` : `${name} is off: only one mod with a mod.ff at a time`, 5000);
      } else if (msg.status === 'started' && msg.role === 'join') {
        showToast(ff ? `Co-op: Halo weapons${ff}; the host's must match` : 'Co-op: the host\'s mods and checkpoints apply', 4500);
      } else if (msg.status === 'started') store.get('armed').then(({ armed = {} }) => {
        const ids = Array.isArray(msg.mods) ? msg.mods : [];
        const names = globalThis.VELGG_MODS.filter(m => ids.includes(m.id) && m.id !== MOD).map(m => m.name + (m.fsGame ? ff : ''));
        const cp = !ids.includes(MOD) ? '' : armed[msg.zone] ? 'Loading your checkpoint…' : `Checkpoints on: ${SAVE_KEY} saves`;
        const text = [names.length ? 'Mods: ' + names.join(', ') : '', cp].filter(Boolean).join(' · ');
        if (text) showToast(text, 4000);
      });
    }
  });
  chrome.storage.onChanged.addListener((changes, area) => {
    if (area === 'local' && (changes.armed || changes.settings)) install(false);
  });
  chrome.runtime.onMessage.addListener((msg, _sender, reply) => {
    if (msg?.type === 'status') {
      // the game's own log files (LogPrint: "halo: ...", "checkpoint: ...") are in OPFS; page.js reads them
      const id = Math.random().toString(36).slice(2);
      // no Halo status a minute after the start: the Halo scripts never ran (most likely the list script inside
      // mod.ff, maps/halo/_halo_list.gsc, was not found, so the mod's scripts failed to link)
      const silent = engineMods.includes('halo') && !modStatus.length && Date.now() - engineStartedAt > 60000;
      const status = silent ? ['halo: no status from the Halo scripts after a minute: they did not run'] : modStatus;
      const done = files => { window.removeEventListener('message', onLogs); reply({ engineZone, log: engineLog.slice(), gameLogs: files, modStatus: status }); };
      const onLogs = event => {
        if (event.source === window && event.data?.[TAG] === 'to-ext' && event.data.type === 'game-logs' && event.data.id === id) {
          clearTimeout(timer); done(Array.isArray(event.data.files) ? event.data.files : []);
        }
      };
      const timer = setTimeout(() => done([]), 2000);
      window.addEventListener('message', onLogs);
      toMain({ type: 'read-logs', id });
      return true; // reply comes later
    }
    else if (msg?.type === 'save-now') { toMain({ type: 'scan', reason: 'manual' }); reply({ ok: true }); }
  });
  toMain({ type: 'ping' });
})();
